package com.drogaria.backend.controller;
import com.drogaria.backend.dto.*; import com.drogaria.backend.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/receita") public class ReceitaController { private final ReceitaService s; private final CarrinhoService a; public ReceitaController(ReceitaService s,CarrinhoService a){this.s=s;this.a=a;} @PostMapping public ResponseEntity<ReceitaResponse> enviar(@Valid @RequestBody ReceitaRequest r,Authentication x){a.validarAcesso(r.getIdCliente(),x);return ResponseEntity.status(HttpStatus.CREATED).body(s.enviar(r));} @GetMapping("/{id}") public ReceitaResponse buscar(@PathVariable Integer id){return s.buscar(id);} @GetMapping("/cliente/{id}") public List<ReceitaResponse> cliente(@PathVariable Integer id,Authentication x){a.validarAcesso(id,x);return s.cliente(id);} @PutMapping("/{id}/aprovar") public ReceitaResponse aprovar(@PathVariable Integer id,@RequestParam Integer idFuncionario){return s.aprovar(id,idFuncionario);} @PutMapping("/{id}/rejeitar") public ReceitaResponse rejeitar(@PathVariable Integer id,@RequestParam String motivo){return s.rejeitar(id,motivo);} }